package com.seasonaldining.recommendation.entity; import jakarta.persistence.*;
@Entity @Table(name="recommendation_messages") public class RecommendationMessage{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="session_id",nullable=false)private Long sessionId;@Column(nullable=false)private String role;@Column(nullable=false,columnDefinition="TEXT")private String content;protected RecommendationMessage(){}public RecommendationMessage(Long s,String r,String c){sessionId=s;role=r;content=c;}public Long getId(){return id;}public String getRole(){return role;}public String getContent(){return content;}}
